source='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    values = {v for row in g for v in row}
    background = max(values, key=lambda v: sum(row.count(v) for row in g))

    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if g[r][c] == background:
                c += 1
                continue
            color, start = g[r][c], c
            while c < w and g[r][c] == color:
                c += 1
            if c - start >= 2:
                bars.append((r, start, c, color))

    bar_color = max(
        {bar[3] for bar in bars},
        key=lambda color: sum(bar[3] == color for bar in bars),
    )
    bars = [bar for bar in bars if bar[3] == bar_color]
    markers = [
        (r, c, g[r][c])
        for r in range(h)
        for c in range(w)
        if g[r][c] not in (background, bar_color)
    ]
    ink = markers[0][2]

    offsets = set()
    for _, c, _ in markers:
        for _, start, end, _ in bars:
            if start <= c < end:
                offsets.add(c - start)
                break

    for r, start, end, _ in bars:
        direction = 1 if r == 0 else -1
        for c in (start + offset for offset in offsets if start + offset < end):
            rr = r + direction
            while 0 <= rr < h and g[rr][c] != bar_color:
                if g[rr][c] == ink:
                    g[rr][c] = 4
                    break
                g[rr][c] = ink
                rr += direction
    return g
